#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

static int bitLen(ll q) { return q > 0 ? 64 - __builtin_clzll((unsigned long long)q) : 0; }

// Coupons needed to bring every price down to at most cap.
static ll couponsToCap(const vector<ll>& a, ll cap) {
    ll total = 0;
    for (ll x : a) if (x > cap) total += bitLen(x / (cap + 1));
    return total;
}

int main() {
    int n; ll m;
    scanf("%d %lld", &n, &m);
    vector<ll> a(n);
    for (auto& x : a) scanf("%lld", &x);
    if (couponsToCap(a, 0) <= m) { puts("0"); return 0; }
    ll lo = 0, hi = *max_element(a.begin(), a.end());
    while (hi - lo > 1) {
        ll mid = (lo + hi) / 2;
        if (couponsToCap(a, mid) <= m) hi = mid; else lo = mid;
    }
    ll used = 0, total = 0;
    for (ll x : a) {
        int steps = x > hi ? bitLen(x / (hi + 1)) : 0;
        used += steps;
        total += x >> steps;
    }
    printf("%lld\n", total - (m - used) * (hi - hi / 2));
}

import java.io.*;

public class Main {
    static long[] a;

    static int bitLen(long q) { return 64 - Long.numberOfLeadingZeros(q); }

    // Coupons needed to bring every price down to at most cap.
    static long couponsToCap(long cap) {
        long total = 0;
        for (long x : a) if (x > cap) total += bitLen(x / (cap + 1));
        return total;
    }

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = (int) readLong(in);
        long m = readLong(in);
        a = new long[n];
        long max = 0;
        for (int i = 0; i < n; i++) { a[i] = readLong(in); max = Math.max(max, a[i]); }
        if (couponsToCap(0) <= m) { System.out.println(0); return; }
        long lo = 0, hi = max;
        while (hi - lo > 1) {
            long mid = (lo + hi) / 2;
            if (couponsToCap(mid) <= m) hi = mid; else lo = mid;
        }
        long used = 0, total = 0;
        for (long x : a) {
            int steps = x > hi ? bitLen(x / (hi + 1)) : 0;
            used += steps;
            total += x >> steps;
        }
        System.out.println(total - (m - used) * (hi - hi / 2));
    }

    static long readLong(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
	"strconv"
)

// Coupons needed to bring every price down to at most cap.
func couponsToCap(a []int64, cp int64) int64 {
	var total int64
	for _, x := range a {
		if x > cp {
			total += int64(bits.Len64(uint64(x / (cp + 1))))
		}
	}
	return total
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 { sc.Scan(); v, _ := strconv.ParseInt(sc.Text(), 10, 64); return v }
	n, m := int(next()), next()
	a := make([]int64, n)
	var mx int64
	for i := range a {
		a[i] = next()
		mx = max(mx, a[i])
	}
	if couponsToCap(a, 0) <= m {
		fmt.Println(0)
		return
	}
	lo, hi := int64(0), mx
	for hi-lo > 1 {
		mid := (lo + hi) / 2
		if couponsToCap(a, mid) <= m {
			hi = mid
		} else {
			lo = mid
		}
	}
	var used, total int64
	for _, x := range a {
		steps := 0
		if x > hi {
			steps = bits.Len64(uint64(x / (hi + 1)))
		}
		used += int64(steps)
		total += x >> steps
	}
	fmt.Println(total - (m-used)*(hi-hi/2))
}
